begin;
set local statement_timeout='20s';
select pg_advisory_xact_lock(1617125,13);
create temporary table batch_input as select * from jsonb_to_recordset($data$[{"shop": "ChicDecorHK", "handle": "cindyzhang62", "listing_id": "1606392268", "source_url": "https://www.etsy.com/listing/1606392268/handmade-large-light-gold-seashell", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "Conch Shell and Freshwater Pearl Necklace", "body": "Large conch shells and freshwater pearls create an ocean-inspired statement necklace from ChicDecorHK. Natural shells vary in surface texture and color. Explore the original listing for details.", "image_url": "https://i.etsystatic.com/32003756/r/il/e53d03/5544130374/il_794xN.5544130374_60kd.jpg", "facebook_draft": "A statement necklace with large conch shells and freshwater pearls from ChicDecorHK. https://www.etsy.com/listing/1606392268/handmade-large-light-gold-seashell", "checked_at": "2026-10-19T02:42:50.918979+00:00", "visual_verified": true, "available": true}, {"shop": "ChicDecorHK", "handle": "cindyzhang62", "listing_id": "1506048129", "source_url": "https://www.etsy.com/listing/1506048129/handmade-conch-shell-earrings-bohemia", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "Conch Shell Drop Earrings for Coastal Outfits", "body": "Pearlescent conch shell drops bring a coastal accent to an outfit. ChicDecorHK offers several size options; natural shell colors and shapes vary. Check the original listing to choose your size.", "image_url": "https://i.etsystatic.com/32003756/r/il/300327/6676993612/il_794xN.6676993612_g6av.jpg", "facebook_draft": "Explore conch shell drop earrings from ChicDecorHK and choose from the listed sizes. https://www.etsy.com/listing/1506048129/handmade-conch-shell-earrings-bohemia", "checked_at": "2026-10-19T02:42:50.919254+00:00", "visual_verified": true, "available": true}, {"shop": "ChicDecorHK", "handle": "cindyzhang62", "listing_id": "1170079452", "source_url": "https://www.etsy.com/listing/1170079452/handmade-conch-shell-earrings-white", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "White Shell Statement Earrings", "body": "White shell drops create a statement look with a coastal feel. Explore the clip and stud options in the ChicDecorHK listing and choose the fitting you prefer. Natural shell shapes and colors vary.", "image_url": "https://i.etsystatic.com/32003756/r/il/c18daf/5008837882/il_794xN.5008837882_8n6o.jpg", "facebook_draft": "White shell statement earrings from ChicDecorHK: check the original listing for clip and stud options. https://www.etsy.com/listing/1170079452/handmade-conch-shell-earrings-white", "checked_at": "2026-10-19T02:42:50.919256+00:00", "visual_verified": true, "available": true}, {"shop": "ChicDecorHK", "handle": "cindyzhang62", "listing_id": "1618224588", "source_url": "https://www.etsy.com/listing/1618224588/handmade-pearl-seashell-necklace-natural", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "Freshwater Pearl Necklace with Colorful Seashells", "body": "Freshwater pearls pair with colorful seashell charms in this handmade ChicDecorHK necklace. A pink scallop shell forms the central accent, with smaller shell details around the strand. Explore the original listing.", "image_url": "https://i.etsystatic.com/32003756/r/il/8c3d9f/5634042237/il_794xN.5634042237_baoj.jpg", "facebook_draft": "Colorful seashell charms and a freshwater pearl strand bring a coastal detail to this ChicDecorHK necklace. https://www.etsy.com/listing/1618224588/handmade-pearl-seashell-necklace-natural", "checked_at": "2026-10-19T02:42:50.919258+00:00", "visual_verified": true, "available": true}, {"shop": "ChicDecorHK", "handle": "cindyzhang62", "listing_id": "1103128579", "source_url": "https://www.etsy.com/listing/1103128579/gold-plated-seashell-necklace-boho", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "Seashell Pendant Necklace in Gold Tones", "body": "A seashell pendant and gold-tone chain add a coastal accent to your jewelry collection. ChicDecorHK offers several shell styles; choose your preferred option and check its details in the original listing.", "image_url": "https://i.etsystatic.com/32003756/r/il/958565/5864086351/il_794xN.5864086351_lhmf.jpg", "facebook_draft": "Explore the shell pendant styles from ChicDecorHK, shown here with a pink-and-white shell and gold-tone chain. https://www.etsy.com/listing/1103128579/gold-plated-seashell-necklace-boho", "checked_at": "2026-10-19T02:42:50.919259+00:00", "visual_verified": true, "available": true}, {"shop": "ChicDecorHK", "handle": "cindyzhang62", "listing_id": "1125022447", "source_url": "https://www.etsy.com/listing/1125022447/handmade-cowrie-shell-hoop-earrings", "category": "Seashell Jewelry", "board_id": "675399344058025061", "new_title": "Shell Hoop Earrings with a Coastal Look", "body": "Spiral shell drops hang from slim hoops in these statement earrings from ChicDecorHK. Several size options are listed, and natural shells vary in shape and color. See the original listing to choose your size.", "image_url": "https://i.etsystatic.com/32003756/r/il/e68c3f/6661859462/il_794xN.6661859462_mrdp.jpg", "facebook_draft": "Shell drops and slim hoops create a coastal statement. Explore the available sizes from ChicDecorHK. https://www.etsy.com/listing/1125022447/handmade-cowrie-shell-hoop-earrings", "checked_at": "2026-10-19T02:42:50.919261+00:00", "visual_verified": true, "available": true}]$data$::jsonb) x(shop text,listing_id text,source_url text,category text,board_id text,new_title text,body text,image_url text,checked_at timestamptz,facebook_draft text,handle text);
do $$ begin
 if not exists(select 1 from pinterest_publish_settings where singleton and enabled and access_tier='standard') then raise exception 'Enabled Standard required'; end if;
 if exists(select 1 from batch_input where checked_at<now()-interval '24 hours' or checked_at>now()) then raise exception 'Verification expired'; end if;
 if (select count(*) from batch_input x join shops s on s.shop_name=x.shop and s.status='active' join shop_social_accounts m on m.shop_id=s.id and m.active and m.platform='pinterest' join social_accounts a on a.id=m.social_account_id and a.handle=x.handle and a.active and a.platform='pinterest' join pinterest_oauth_credentials cr on cr.social_account_id=a.id and lower(cr.pinterest_username)=x.handle)<>6 then raise exception 'Batch routing or authorization changed'; end if;
end $$;
-- Report prior records before inserting; only genuinely new products enter this batch.
select json_build_object('preexisting_listing',p.etsy_listing_id,'history_count',(select count(*) from publish_history h where h.product_id=p.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id;
create temporary table new_products(id uuid,shop_id uuid,etsy_listing_id text);
with ins as (
 insert into products(shop_id,etsy_listing_id,etsy_url,title,category,listing_status,primary_image_url,original_image_urls,source_payload,source_discovered_at,last_seen_at)
 select s.id,x.listing_id,x.source_url,x.new_title,x.category,'active',x.image_url,jsonb_build_array(x.image_url),jsonb_build_object('verified_at',x.checked_at,'source',x.source_url,'image_verified',true,'batch','daily-20261019-b14'),x.checked_at,x.checked_at from batch_input x join shops s on s.shop_name=x.shop
 where not exists(select 1 from products p where p.etsy_listing_id=x.listing_id)
 on conflict(shop_id,etsy_listing_id) do nothing returning id,shop_id,etsy_listing_id
) insert into new_products select * from ins;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'pinterest','verified-original-20261019',x.image_url,x.new_title,x.body,x.source_url,x.category,'product','ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into content_variants(shop_id,product_id,platform,creative_id,image_url,title,body,destination_url,board_or_category,content_type,status)
select p.shop_id,p.id,'facebook','verified-original-20261019',x.image_url,x.new_title,x.facebook_draft,x.source_url,x.category,'product','draft' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id;
insert into publish_queue(shop_id,product_id,content_variant_id,platform,social_account_id,status)
select p.shop_id,p.id,cv.id,'pinterest',a.id,'ready' from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join content_variants cv on cv.product_id=p.id and cv.platform='pinterest' join social_accounts a on a.handle=x.handle and a.platform='pinterest';
insert into pinterest_publish_reviews(queue_id,board_id,snapshot,listing_checked_at,source_url)
select q.id,x.board_id,pinterest_publish_snapshot(q.id),x.checked_at,x.source_url from new_products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest';
select json_build_object('listing_id',p.etsy_listing_id,'queue_id',q.id,'status',q.status,'board_id',r.board_id,'snapshot_matches',r.snapshot=pinterest_publish_snapshot(q.id)) from products p join batch_input x on x.listing_id=p.etsy_listing_id join publish_queue q on q.product_id=p.id and q.platform='pinterest' join pinterest_publish_reviews r on r.queue_id=q.id;
commit;
